-- generated by tools/gencatalog, do not edit by hand

CREATE TABLE grades (
    id BIGINT PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
    code VARCHAR(64) NOT NULL,
    name VARCHAR(128) NOT NULL,
    rank INTEGER CHECK (rank BETWEEN 1 AND 100) NOT NULL,
    is_deleted BOOLEAN NOT NULL DEFAULT FALSE
);

CREATE TABLE grade_revisions (
    id              BIGINT       PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
    grade_id BIGINT       NOT NULL REFERENCES grades(id) ON DELETE CASCADE,
    revision_number INTEGER      NOT NULL CHECK (revision_number >= 1),
    change          JSONB        NOT NULL,
    changed_by      UUID         NOT NULL,
    changed_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),

    CONSTRAINT uq_grade_revisions_revision
        UNIQUE (grade_id, revision_number)
);

CREATE UNIQUE INDEX uq_grades_code
    ON grades (code);

CREATE INDEX idx_grades_active
    ON grades (id)
    WHERE is_deleted = FALSE;

CREATE INDEX idx_grade_revisions_grade_id
    ON grade_revisions (grade_id);

CREATE INDEX idx_grade_revisions_covering_agg
    ON grade_revisions (grade_id, revision_number DESC)
    INCLUDE (changed_at, changed_by, change);

CREATE INDEX idx_grade_revisions_changed_at
    ON grade_revisions (changed_at);

CREATE OR REPLACE VIEW v_expanded_grade AS
SELECT
    t.id,
    t.code,
    t.name,
    t.rank,
    t.is_deleted,
    agg.revision,
    agg.last_changer,
    agg.created_at,
    agg.updated_at,
    agg.deleted_at
FROM grades t
LEFT JOIN (
    SELECT
        grade_id,
        MAX(revision_number) AS revision,
        MAX(changed_at) AS updated_at,
        (ARRAY_AGG(changed_by ORDER BY revision_number DESC))[1] AS last_changer,
        MIN(changed_at) FILTER (WHERE revision_number = 1) AS created_at,
        MAX(changed_at) FILTER (
            WHERE change @> '[{"path": "/is_deleted", "value": true}]'::jsonb
        ) AS deleted_at
    FROM grade_revisions
    GROUP BY grade_id
) agg ON agg.grade_id = t.id;

COMMENT ON TABLE grades IS
    'Qualification grades of employees used by the planning of work. Stores the current state of each record.';

COMMENT ON TABLE grade_revisions IS
    'Immutable audit log of changes applied to grades. Read-only from the application perspective.';

COMMENT ON VIEW v_expanded_grade IS
    'Read-only view that enriches each grade with its latest revision number, '
    'last changer UUID, and lifecycle timestamps derived from the revision log.';
